import{_ as t,o as n,c as i,a4 as s}from"./chunks/framework.BE47AOxC.js";const b=JSON.parse(`{"title":"ADR-0055 — La lecture publique d'une fiche publiée n'est pas journalisée","description":"Extrait de docs/adr/0055-lecture-publique-d-une-fiche-non-journalisee.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0055 — La lecture publique d'une fiche publiée n'est pas journalisée","description":"Extrait de docs/adr/0055-lecture-publique-d-une-fiche-non-journalisee.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0055-lecture-publique-d-une-fiche-non-journalisee.md","filePath":"developpeurs/adr/0055-lecture-publique-d-une-fiche-non-journalisee.md"}`),l={name:"developpeurs/adr/0055-lecture-publique-d-une-fiche-non-journalisee.md"};function a(u,e,r,o,c,d){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0055--la-lecture-publique-dune-fiche-publiée-nest-pas-journalisée" tabindex="-1">ADR-0055 — La lecture publique d&#39;une fiche publiée n&#39;est pas journalisée <a class="header-anchor" href="#adr-0055--la-lecture-publique-dune-fiche-publiée-nest-pas-journalisée" aria-label="Permalink to &quot;ADR-0055 — La lecture publique d&#39;une fiche publiée n&#39;est pas journalisée {#adr-0055--la-lecture-publique-dune-fiche-publiée-nest-pas-journalisée}&quot;">​</a></h1><p><strong>Date :</strong> 26 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constat RGPD-12 (à trancher)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Un type de contenu peut porter des données personnelles (<code>contains_personal_data</code>) et être publié : l&#39;annuaire des élus, la liste des associations et de leurs responsables. Le journal d&#39;accès aux données personnelles (CDC §13.1, E5) enregistre la lecture du détail d&#39;une fiche dans le back-office.</p><p>L&#39;audit relève une incohérence entre deux surfaces publiques :</p><ul><li><code>/api/v1/public/resolve</code> et les listes publiques servent ces fiches sans rien journaliser ;</li><li>l&#39;assistant public (<code>app/ai_editorial/public_assistant.py</code>), lui, journalise la lecture des fiches porteuses qu&#39;il cite dans une réponse.</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><strong>Une fiche publiée et visible de tous est publique.</strong> Sa lecture par un visiteur, par <code>/public/resolve</code>, par une liste, un flux ou le plan de site, <strong>n&#39;est pas journalisée</strong>. Le journal d&#39;accès trace qui, parmi les personnes habilitées, a consulté des données qui ne sont pas publiques. Une lecture anonyme d&#39;une donnée que la collectivité a choisi de publier n&#39;en fait pas partie.</li><li><strong>Le choix de publier est l&#39;acte qui compte</strong>, et il est déjà tracé : c&#39;est un agent identifié qui publie, et le cycle de vie de la fiche le garde (<code>content_lifecycle_events</code>). La base légale de la publication (mission d&#39;intérêt public, obligation légale, consentement de l&#39;élu) se déclare au registre des traitements.</li><li><strong>Ce qui reste journalisé ne change pas</strong> : <ul><li>toute lecture du détail dans le back-office ;</li><li>toute fiche <strong>non publique</strong> : brouillon, page ou fiche à accès restreint lue par un usager connecté, champ déclaré non public ;</li><li>l&#39;assistant public, qui continue de journaliser ce qu&#39;il cite. Il compose une réponse à partir de sources, et la trace de ce qu&#39;il a assemblé reste utile. Cette différence est voulue, pas un oubli.</li></ul></li><li><strong>Aucune adresse IP</strong> ni identifiant de visiteur n&#39;est collecté pour cette lecture.</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Une ligne de journal par lecture publique de détail</strong></td><td>Le journal deviendrait un journal de trafic. Il ne distinguerait plus un accès sensible d&#39;une visite, et chaque visite d&#39;une fiche d&#39;élu écrirait en base.</td></tr><tr><td><strong>Journaliser seulement les types porteurs et non publiés à tous</strong></td><td>C&#39;est déjà le cas : un contenu non public n&#39;est jamais servi à un anonyme.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Le journal d&#39;accès garde son sens : qui, parmi les habilités, a lu une donnée personnelle non publique.</li><li>Aucune écriture en base à chaque visite publique.</li></ul><p><strong>Négatives</strong></p><ul><li>Personne ne peut dire combien de fois la fiche d&#39;un élu a été consultée publiquement. Ce n&#39;est pas l&#39;objet du journal RGPD, et une mesure d&#39;audience sort du périmètre du Core.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><p>Aucune.</p>',17)])])}const h=t(l,[["render",a]]);export{b as __pageData,h as default};
